-- Migration générée : ne pas éditer à la main.
-- Régénérer avec : pnpm genere:actor-alias
--
-- Source : MISP Galaxy clusters/ransomware.json + clusters/threat-actor.json
-- Chaque alias porte la grappe qui l'atteste. Une fusion sans source
-- est impossible : `source` et `source_url` sont NOT NULL et non vides.

CREATE TABLE IF NOT EXISTS actor_alias (
  id          bigserial PRIMARY KEY,
  canonique   text NOT NULL,
  alias       text NOT NULL,
  alias_norm  text NOT NULL,
  source      text NOT NULL,
  source_url  text NOT NULL,
  galaxy_uuid uuid,
  imported_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT actor_alias_canonique_non_vide CHECK (btrim(canonique) <> ''),
  CONSTRAINT actor_alias_alias_non_vide CHECK (btrim(alias) <> ''),
  CONSTRAINT actor_alias_alias_norm_non_vide CHECK (btrim(alias_norm) <> ''),
  CONSTRAINT actor_alias_source_non_vide CHECK (btrim(source) <> '' AND btrim(source_url) <> ''),
  CONSTRAINT actor_alias_alias_source_unique UNIQUE (alias, source, source_url)
);

CREATE INDEX IF NOT EXISTS actor_alias_canonique_idx ON actor_alias (canonique);
CREATE INDEX IF NOT EXISTS actor_alias_norm_idx ON actor_alias (alias_norm);

COMMENT ON TABLE actor_alias IS
  'Alias d''acteurs et de programmes rançongiciel issus de MISP Galaxy ; chaque ligne porte sa source.';

ON CONFLICT ON CONSTRAINT actor_alias_alias_source_unique DO NOTHING;
